import {execFileSync} from 'node:child_process';
import {resolve} from 'node:path';
const backend=resolve('release/packages/backend');
let phase='target';
const cli=args=>execFileSync(process.execPath,['node_modules/convex/bin/main.js',...args],{cwd:backend,encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout:30000,maxBuffer:2*1024*1024}).trim();
const query=(source,component)=>JSON.parse(cli(['run','--inline-query',source,...(component?['--component',component]:[])]));
const check=x=>{if(!x)throw Error();};
try{
 check(cli(['dashboard','--no-open']).match(/https:\/\/dashboard\.convex\.dev\/d\/([a-z0-9-]+)/)?.[1]==='woozy-wren-368');
 phase='exact-fixture';
 const own=query(`const invites=await ctx.db.query("betaInvites").order("desc").take(100);
const foundation=invites.filter(x=>typeof x.email==="string"&&x.email.includes("+pikar-foundation-"));
if(foundation.length!==1)return {failure:"AMBIGUOUS"};const original=foundation[0].email;const at=original.lastIndexOf("@");const local=original.slice(0,at).split("+pikar-foundation-")[0];const domain=original.slice(at);if(!local||domain!=="@gmail.com")return {failure:"OWNER"};
const users=await ctx.db.query("users").order("desc").take(100);const own=users.filter(x=>typeof x.email==="string"&&x.email.startsWith(local+"+pikar-native-signup-")&&x.email.endsWith(domain));
if(own.length!==1||Date.now()-own[0]._creationTime>7200000||own[0]._creationTime>Date.now())return {failure:"FRESHNESS"};
const accounts=await ctx.db.query("authAccounts").withIndex("userIdAndProvider",q=>q.eq("userId",own[0]._id).eq("provider","password")).take(2);if(accounts.length!==1||accounts[0].emailVerified!==own[0].email)return {failure:"ACCOUNT_VERIFICATION"};
if(!Number.isFinite(own[0].emailVerificationTime)||own[0].emailVerificationTime<own[0]._creationTime||own[0].emailVerificationTime>Date.now())return {failure:"USER_VERIFICATION_METADATA"};
const admission=invites.filter(x=>x.email===own[0].email);if(admission.length!==1||admission[0].redeemedUserId!==own[0]._id)return {failure:"ADMISSION"};

const tenantId=String(own[0]._id);const interviews=await ctx.db.query("foundationInterviews").withIndex("by_tenant",q=>q.eq("tenantId",tenantId)).take(2);if(interviews.length!==1||interviews[0].revision!==9||interviews[0].publishedRevision!==9)return {failure:"REVISION"};
const docs=await ctx.db.query("vaultDocuments").withIndex("by_tenant",q=>q.eq("tenantId",tenantId)).take(8);const failed=docs.filter(d=>d.status==="failed"&&d.kind==="business_foundation_delivery");if(docs.length!==7||failed.length!==1||docs.filter(d=>d.status==="ready").length!==6)return {failure:"DOCUMENT_SCOPE"};if(typeof failed[0].contentHash!=="string"||!failed[0].contentHash)return {failure:"HASH"};return {tenantId,docId:failed[0]._id,hash:failed[0].contentHash};`);
 check(own&&!own.failure&&typeof own.tenantId==='string'&&typeof own.docId==='string'&&typeof own.hash==='string');
 phase='workflow-diagnostic';
 const evidence=query(`const expected=${JSON.stringify(own)};const all=await ctx.db.query("workflows").take(1001);if(all.length>1000)return {failure:"WORKFLOW_BOUND"};const matches=all.filter(w=>w.onComplete?.context?.tenantId===expected.tenantId&&w.onComplete?.context?.vaultDocId===expected.docId&&w.args?.tenantId===expected.tenantId&&w.args?.vaultDocId===expected.docId&&w.args?.expectedContentHash===expected.hash);if(matches.length!==1)return {failure:"WORKFLOW_SELECTION"};const w=matches[0];const rows=await ctx.db.query("steps").withIndex("workflow",q=>q.eq("workflowId",w._id)).take(51);if(rows.length>50)return {failure:"STEP_BOUND"};
const codes=["PAID_DAILY_BUDGET_EXHAUSTED","PAID_DEPLOYMENT_BUDGET_EXHAUSTED","PAID_KILL_SWITCH","PAID_ADMISSION_INVALID","PAID_SETTLEMENT_MISMATCH","EVAL_DAILY_BUDGET_EXHAUSTED","EVAL_DEPLOYMENT_BUDGET_EXHAUSTED","PAID_BILLING_MODE_UNVERIFIED","PAID_COST_UNKNOWN","PAID_MODEL_RESPONSE_UNRESOLVED","PAID_MODEL_UNSUPPORTED","PAID_PROVIDER_EXCEEDED_RESERVATION","PAID_BUDGET_EXCEEDED","BUDGET_EXCEEDED","DAILY_BUDGET_EXCEEDED","EVAL_SOURCE_MISSING","EVAL_EMBEDDING_PREVIOUS_FAILURE","EVAL_EMBEDDING_PROVIDER_FAILED","EVAL_EMBEDDING_RESPONSE_UNRESOLVED","EVAL_PROVIDER_EXCEEDED_RESERVATION","UNAUTHENTICATED","TENANT_ERASURE_REQUIRED"];
const classify=result=>{if(!result||result.kind!=="failed")return {category:"not_failed",codes:[]};const error=typeof result.error==="string"?result.error:"";const found=codes.filter(code=>new RegExp("\\b"+code+"\\b").test(error));const category=/NoObjectGenerated|No object generated|JSON.*parse|schema.*match/i.test(error)?"model_output":/budget|reservation|spend limit|daily limit/i.test(error)?"budget":/timed? ?out|timeout|deadline/i.test(error)?"timeout":/429|rate.?limit|too many requests/i.test(error)?"provider_rate_limit":/401|403|api.?key|unauthorized|forbidden/i.test(error)?"provider_auth":/provider|openrouter|openai|fetch failed|502|503|504/i.test(error)?"provider":/journal|component|workpool|validator|argumentvalidation|document.*not.*found/i.test(error)?"component":"unclassified";return {category,codes:found};};
const names=["guardrails:preCall","vault:markFailed","vaultRag:embedDoc","vaultLlm:extractGraph","vaultGraph:upsertGraph","vaultLlm:classifyDoc","vault:applyClassification","guardrails:recordSpend","vault:markReady"];
const resultKind=r=>["success","failed","canceled"].includes(r?.kind)?r.kind:"pending";
return {exactFixtureMatched:true,exactContentWorkflowMatched:true,workflowInventoryComplete:true,runResultKind:resultKind(w.runResult),failure:classify(w.runResult),steps:rows.map(r=>({name:names.includes(r.step.name)?r.step.name:"unrecognized",runResultKind:resultKind(r.step.runResult),inProgress:r.step.inProgress===true,failure:classify(r.step.runResult)})),readOnly:true,providerCallsRequested:false};`,'workflow');
 check(evidence?.exactFixtureMatched===true&&evidence?.exactContentWorkflowMatched===true);
 phase='ledger-summary';
 const ledger=query(`const rows=await ctx.db.query("spendEvents").withIndex("by_tenant",q=>q.eq("tenantId",${JSON.stringify(own.tenantId)})).take(1001);if(rows.length>1000)return {failure:"LEDGER_BOUND"};const sums={reservedCents:0,actualCents:0,refundedCents:0,adjustmentCents:0};for(const row of rows){if(!Number.isFinite(row.amountCents))return {failure:"LEDGER_AMOUNT"};const field={reserved:"reservedCents",actual:"actualCents",refunded:"refundedCents",adjustment:"adjustmentCents"}[row.phase];if(field)sums[field]+=row.amountCents;}const groups=new Map();for(const row of rows){if(!groups.has(row.correlationId))groups.set(row.correlationId,[]);groups.get(row.correlationId).push(row);}let unresolvedReservedCents=0;for(const group of groups.values()){if(!group.some(r=>r.phase==="actual"))unresolvedReservedCents+=Math.max(0,group.filter(r=>r.phase==="reserved").reduce((n,r)=>n+r.amountCents,0)-group.filter(r=>r.phase==="refunded").reduce((n,r)=>n+r.amountCents,0));}return {...sums,unresolvedReservedCents,ledgerRowCount:rows.length,complete:true};`);
 check(ledger?.complete===true);
 console.log(JSON.stringify({...evidence,ledger}));
}catch{console.error(JSON.stringify({diagnosticSucceeded:false,phase,privateDiagnosticsSuppressed:true}));process.exitCode=1;}
